INSERT INTO prestaciones(nombre,descripcion,activo) VALUES ('Baño higiénico','Limpieza y secado para mascotas',true),('Corte de pelo','Corte y acabado del pelaje',true),('Paquete Baño + Corte','Incluye baño higiénico y corte de pelo',true),('Paquete Preventivo','Consulta veterinaria y vacunación',true) ON CONFLICT(nombre) DO NOTHING;
INSERT INTO prestacion_componentes SELECT p.id,c.id FROM prestaciones p CROSS JOIN prestaciones c WHERE (p.nombre='Paquete Baño + Corte' AND c.nombre IN ('Baño higiénico','Corte de pelo')) OR (p.nombre='Paquete Preventivo' AND c.nombre IN ('Consulta veterinaria','Vacunación')) ON CONFLICT DO NOTHING;
INSERT INTO sede_prestacion(id_sede,id_prestacion,precio,duracion_minutos,activo) SELECT s.id,p.id,CASE WHEN p.nombre='Paquete Preventivo' THEN 90.00 ELSE 65.00 END,60,true FROM sedes s CROSS JOIN prestaciones p WHERE s.nombre IN ('Garritas Miraflores','Garritas Los Olivos','Garritas Cayma','Garritas Trujillo Centro','Garritas Wanchaq','Garritas El Tambo') AND p.nombre IN ('Paquete Baño + Corte','Paquete Preventivo') ON CONFLICT(id_sede,id_prestacion) DO NOTHING;
